CREATE TABLE t1 (id INT);
DELIMITER //
CREATE PROCEDURE p1()
BEGIN
  INSERT INTO t1 VALUES (1);
  IF 1 = 1 THEN
    CREATE TABLE inside (x INT);
  END IF;
END //
DELIMITER ;
CREATE TRIGGER trg BEFORE INSERT ON t1 FOR EACH ROW SET NEW.id = NEW.id + 1;
CREATE TABLE t2 (id INT, t1_id INT, FOREIGN KEY fk_name (t1_id) REFERENCES t1 (id));
CREATE VIEW v AS SELECT * FROM t1;
